import ProductDialog from "./ProductDialog.vue";
import EditProductDialog from "./EditProductDialog.vue";
import DeleteProductDialog from "./DeleteProductDialog.vue";
import StockAdjustmentDialog from "./StockAdjustmentDialog.vue";
import SnackBar from "@/components/SnackBar.vue";
import ServiceDialog from "./ServiceDialog.vue";
import EditServiceDialog from "./EditServiceDialog.vue";
import DeleteServiceDialog from "./DeleteServiceDialog.vue";
import { list_items, get_items_transactions } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import BulkItemImport from "./BulkItemImport.vue";
import { export_inventory_items } from "@/graphql/mutations.js";
import { getS3SignedUrl } from "@/mixins/S3GetStorageFile.js";
const FileSaver = require("file-saver");
import * as XLSX from "xlsx";
import axios from "axios";
export default {
  name: "Product",
  components: {
    ProductDialog,
    EditProductDialog,
    DeleteProductDialog,
    StockAdjustmentDialog,
    SnackBar,
    ServiceDialog,
    EditServiceDialog,
    DeleteServiceDialog,
    BulkItemImport
  },
  data() {
    return {
      products: [],
      selectedProduct: null,
      searchProduct: "",
      productDialog: false,
      editProductDialog: false,
      editingProduct: null,
      deleteProductDialog: false,
      productToDelete: null,
      serviceDialog: false,
      editServiceDialog: false,
      editingService: null,
      deleteServiceDialog: false,
      serviceToDelete: null,
      stockAdjustmentDialog: false,
      saving: false,
      windowHeight: 0,
      tableLoading: false,
      SnackBarComponent: {},
      // Filter properties
      selectedFilter: "PRODUCT",
      filterOptions: [{
        title: "Goods",
        value: "PRODUCT"
      }, {
        title: "Services",
        value: "SERVICE"
      }],
      serviceTableHeight: 0,
      // Transaction table properties
      searchTransaction: "",
      transactionLoading: false,
      transactionCurrentPage: 1,
      transactionItemsPerPage: 10,
      totalTransactions: 0,
      transactions: [],
      // Mock data for now
      transactionHeaders: [{
        title: "TYPE",
        value: "transaction_type_name",
        sortable: true
      }, {
        title: "TRANSACTION TYPE",
        value: "transaction_type",
        sortable: true
      }, {
        title: "NAME",
        value: "transaction_details",
        sortable: true
      }, {
        title: "DATE",
        value: "transaction_date",
        sortable: true
      }, {
        title: "QUANTITY",
        value: "stock_quantity",
        sortable: true
      }, {
        title: "STOCK VALUE",
        value: "stock_value",
        sortable: true
      }
      //  { title: "TRACKING", value: "tracking_type", sortable: true },
      ],
      productHeaders: [{
        title: "Item Name",
        value: "item_name",
        sortable: true
      }, {
        title: "Sale Quantity",
        value: "item_unit_text",
        sortable: true
      }, {
        title: "Sale Price",
        value: "sale_price",
        sortable: true
      }, {
        title: "Stock Quantity",
        value: "stock_quantity",
        sortable: true
      }, {
        title: "",
        value: "action",
        sortable: false
      }],
      transactionTableHeight: 0,
      productDetailsDialog: false,
      exportLoading: false,
      templateLoading: false,
      actionLoading: false // ✅ stop Actions loader
    };
  },
  computed: {
    filteredProducts() {
      let filtered = this.products;
      console.log(filtered);

      // Filter by type (PRODUCT/SERVICE)
      if (this.selectedFilter) {
        filtered = filtered.filter(product => product.item_type === this.selectedFilter);
      }

      // Filter by search query
      if (this.searchProduct) {
        filtered = filtered.filter(product => product.item_name.toLowerCase().includes(this.searchProduct.toLowerCase()) || product.stock_quantity && product.stock_quantity.toString().toLowerCase().includes(this.searchProduct.toLowerCase()));
      }
      return filtered;
    },
    productTableItems() {
      return this.filteredProducts.map(p => ({
        ...p,
        sale_price: p.sale_price?.sale_price || 0
      }));
    },
    // Transaction table computed properties
    filteredTransactions() {
      if (!this.searchTransaction) return this.transactions;
      const searchLower = this.searchTransaction.toLowerCase();
      return this.transactions.filter(item => item.transaction_type_name?.toLowerCase().includes(searchLower) || item.transaction_type?.toLowerCase().includes(searchLower) || item.transaction_name?.toLowerCase().includes(searchLower) || item.tracking_type?.toLowerCase().includes(searchLower));
    },
    transactionPageCount() {
      return Math.ceil(this.totalTransactions / this.transactionItemsPerPage);
    },
    visibleTransactionPages() {
      const pages = [];
      const start = Math.max(1, this.transactionCurrentPage - 2);
      const end = Math.min(this.transactionPageCount, this.transactionCurrentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async mounted() {
    this.windowHeight = window.innerHeight - 280;
    this.transactionTableHeight = window.innerHeight - 460;
    this.serviceTableHeight = window.innerHeight - 300;
    await this.getProducts();
    // Select first product by default
  },
  watch: {
    // Watch for filter changes and handle product selection
    selectedFilter() {
      this.handleFilterChange();
    }
  },
  methods: {
    async getProducts() {
      this.tableloading = true;
      try {
        const result = await API.graphql(graphqlOperation(list_items));
        // console.log(result);
        const resultData = JSON.parse(result.data.list_items);
        // console.log(resultData);
        if (resultData.Status == "SUCCESS") {
          this.products = resultData.data;
          console.log("products", this.products);
          this.tableloading = false;

          // Select first product based on current filter
          // if (this.products.length > 0) {
          //   // Find first product that matches current filter
          //   const firstMatchingProduct = this.products.find(
          //     product => product.item_type === this.selectedFilter
          //   );

          //   if (firstMatchingProduct) {
          //     this.selectProduct(firstMatchingProduct);
          //   } else if (this.products.length > 0) {
          //     // If no product matches filter, select first available
          //     this.selectProduct(this.products[0]);
          //   }
          // }
        } else {
          this.tableloading = false;
          this.products = [];
        }
      } catch (error) {
        this.products = [];
        console.log(error);
        this.tableloading = false;
      }
    },
    selectProduct(event, product) {
      console.log(product);
      this.selectedProduct = product.item;
      this.productDetailsDialog = true; // 🔥 open dialog
      this.transactionCurrentPage = 1; // reset pagination
      this.loadTransactionData();
    },
    handleFilterChange() {
      // Check if current selected product is still visible after filter change
      if (this.selectedProduct) {
        const isStillVisible = this.filteredProducts.some(product => product.item_id === this.selectedProduct.item_id);
        if (!isStillVisible) {
          // Current product is no longer visible, select first available product
          if (this.filteredProducts.length > 0) {
            this.selectProduct(this.filteredProducts[0]);
          } else {
            // No products available in current filter, clear selection
            this.selectedProduct = null;
            this.transactions = [];
            this.totalTransactions = 0;
          }
        }
      } else if (this.filteredProducts.length > 0) {
        // No product was selected but we have filtered products, select first one
        this.selectProduct(this.filteredProducts[0]);
      }
    },
    addProduct() {
      if (this.selectedFilter === "SERVICE") {
        this.editingService = null;
        this.serviceDialog = true;
      } else {
        this.editingProduct = null;
        this.productDialog = true;
      }
    },
    editProduct(product) {
      if (this.selectedFilter === "SERVICE") {
        this.editingService = product;
        this.editServiceDialog = true;
      } else {
        this.editingProduct = product;
        console.log("this.editingProduct", this.editingProduct);
        this.editProductDialog = true;
      }
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.products = [];
      this.selectedProduct = null;
      this.productDialog = false;
      this.editProductDialog = false;
      this.deleteProductDialog = false;
      this.serviceDialog = false;
      this.editServiceDialog = false;
      this.deleteServiceDialog = false;
      this.getProducts();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    deleteProduct(product) {
      if (this.selectedFilter === "SERVICE") {
        this.serviceToDelete = product;
        this.deleteServiceDialog = true;
      } else {
        this.productToDelete = product;
        this.deleteProductDialog = true;
      }
    },
    openStockAdjustment() {
      this.stockAdjustmentDialog = true;
    },
    handleTransactionSortChange(value) {
      // console.log("Transaction sort changed:", value);
    },
    getTransactionTypeColor(type) {
      switch (type?.toLowerCase()) {
        case "opening stock":
          return "blue";
        case "add adjustment":
          return "green";
        case "reduce adjustment":
          return "orange";
        case "purchase":
          return "purple";
        case "sale":
          return "teal";
        default:
          return "grey";
      }
    },
    getTransactionTypeIcon(type) {
      switch (type?.toLowerCase()) {
        case "opening stock":
          return "mdi-package-variant-plus";
        case "add adjustment":
          return "mdi-plus-circle";
        case "reduce adjustment":
          return "mdi-minus-circle";
        case "purchase":
          return "mdi-cart-arrow-down";
        case "sale":
          return "mdi-cart-arrow-up";
        default:
          return "mdi-circle";
      }
    },
    getStatusColor(status) {
      switch (status?.toLowerCase()) {
        case "completed":
          return "green";
        case "pending":
          return "orange";
        case "cancelled":
          return "red";
        case "processing":
          return "blue";
        default:
          return "grey";
      }
    },
    getStockColor(quantity) {
      const qty = parseFloat(quantity) || 0;
      if (qty < 0) return "red";
      if (qty >= 0) return "green";
      return "grey";
    },
    // Load mock transaction data when product is selected
    async loadTransactionData() {
      if (this.selectedProduct) {
        try {
          const result = await API.graphql(graphqlOperation(get_items_transactions, {
            input: {
              item_id: this.selectedProduct.item_id,
              limit: 100,
              nextToken: null
            }
          }));
          const resultData = JSON.parse(result.data.get_items_transactions);
          if (resultData.Status == "SUCCESS") {
            this.transactions = resultData.data;
            this.totalTransactions = resultData.data.length;
          } else {
            this.transactions = [];
            this.totalTransactions = 0;
          }
          // console.log(resultData);
        } catch (error) {
          console.log(error);
        }
        this.totalTransactions = this.transactions.length;
      }
    },
    async download_item() {
      try {
        this.templateLoading = true;
        this.actionLoading = true; // 🔥 activate Actions loader

        const headers = ["item_name", "item_type", "item_code", "item_hsn", "category_name", "sub_category_name", "item_unit", "tracking_type", "purchase_price", "sale_price", "whole_sale_price", "stock_quantity", "stock_value", "minimum_stock", "discount_price", "item_tax", "item_description", "item_location"];
        let teamId = this.$store.getters.GetUserObj?.organization?.organization_team_id || "";
        let fileName = teamId ? `${teamId}_Inventory Template.xlsx` : "Inventory Template.xlsx";
        const ws = XLSX.utils.aoa_to_sheet([headers]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
        XLSX.writeFile(wb, fileName);
      } finally {
        this.templateLoading = false;
        this.actionLoading = false; // ✅ stop Actions loader
      }
    },
    handleSuccess({
      results,
      header
    }) {
      this.$router.push("/home/BulkUploadInventory");
      let customerData = {
        excelHeaders: header,
        excelTableData: results
      };
      this.$store.commit("SetcustomerDetails", customerData);
    },
    beforeUpload(file) {
      const isLt1M = file.size / 1024 / 1024 < 5;
      return isLt1M;
    },
    async export_item() {
      try {
        this.exportLoading = true;
        this.actionLoading = true; // 🔥 start Actions loader

        const data = this.$store.getters.GetUserObj;
        const result = await API.graphql(graphqlOperation(export_inventory_items, {
          input: {
            user_email_id: data.organization.organization_created_by,
            item_type: "ALL",
            category_id: "ALL"
          }
        }));
        const response = JSON.parse(result.data.export_inventory_items);
        if (response.Status === "SUCCESS" && response.URL) {
          await this.download_items(response.URL, response.FileName);
          this.actionLoading = false; // ✅ stop Actions loader
        } else {
          throw new Error(response.Message || "Export failed");
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.message || error.errors?.[0]?.message,
          timeout: 5000,
          Top: true
        };
      } finally {
        this.exportLoading = false;
        this.actionLoading = false; // ✅ stop Actions loader
      }
    },
    async download_items(url, fileNameFromApi) {
      let teamId = this.$store.getters.GetUserObj?.organization?.organization_team_id || "";
      let fileName = fileNameFromApi ? `${teamId}_${fileNameFromApi}` : `${teamId}_Inventory.xlsx`;
      try {
        const response = await axios({
          url,
          method: "GET",
          responseType: "blob"
        });
        const blob = new Blob([response.data], {
          type: response.headers["content-type"] || "application/octet-stream"
        });
        FileSaver.saveAs(blob, fileName);
        this.actionLoading = false; // ✅ stop Actions loader
      } catch (error) {
        console.error("Download failed:", error);
        this.actionLoading = false; // ✅ stop Actions loader
      }
    }
  }
};
